   "events": [
    {
     "year": 2022,
     "metrics": [
      "total_equity"
     ],
     "nature": "accounting",
     "title": "Rising interest rates cut IFRS 4 equity",
     "detail": "Bond prices fell as rates rose in 2022. Under IFRS 4/IAS 39, unrealised losses on available-for-sale bonds reduced equity through other comprehensive income (OCI) — while the matching decrease in the economic value of liabilities was not fully reflected. Net income was unaffected; equity fell sharply.",
     "where_to_verify": "Statement of comprehensive income (OCI); statement of changes in equity; notes on financial assets."
    },
    {
     "year": 2023,
     "metrics": [
      "revenue",
      "total_equity",
      "net_income",
      "total_liabilities",
      "eps"
     ],
     "nature": "accounting",
     "title": "Adoption of IFRS 17 and IFRS 9",
     "detail": "From 2023 insurance revenue replaces premiums (investment components are excluded), the unearned profit on in-force business sits in the contractual service margin (a liability), and equity is measured differently. Revenue and equity before and after 2023 are not comparable — the decline is accounting-driven, not a collapse in business.",
     "where_to_verify": "Annual Report 2023: note on changes in accounting policies / transition to IFRS 17 and IFRS 9 (restated 2022 comparatives)."
    },
    {
     "year": 2024,
     "metrics": [
      "eps",
      "total_equity"
     ],
     "nature": "capital",
     "title": "Share buybacks and rising dividends",
     "detail": "Swiss Life returned capital through buybacks, reducing the share count, which supports EPS growth beyond net income growth.",
     "where_to_verify": "Statement of changes in equity (treasury shares); EPS note; capital management section."
    }
   ],
   "top_risks_reference": [
    {
     "risk": "interest_rate",
     "why": "The savings result depends on the spread between investment yields and guaranteed rates; low or falling rates and reinvestment risk compress margins and the SST ratio."
    },
    {
     "risk": "market",
     "why": "A large real-estate and equity exposure plus fee income linked to asset values: a property downturn hits investment results, solvency and asset-management fees."
    },
    {
     "risk": "regulatory",
     "why": "Swiss pension politics (BVG conversion rate, legal quote) and SST changes can cap profitability of the Swiss group-life business and change capital requirements."
    }
   ],
